// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.bulk;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.mockito.ArgumentCaptor;

class BulkLoadProgressTest {

	@TempDir
	Path temporaryDirectory;

	@Test
	void limitsListenerUpdatesToOnePerMillionOperationsWhileSamplingPersists() throws Exception {
		List<ProgressSnapshot> snapshots = new ArrayList<>();
		ScheduledExecutorService sampler = mock();
		ArgumentCaptor<Runnable> scheduledSample = ArgumentCaptor.forClass(Runnable.class);
		try (BulkLoadProgress progress = new BulkLoadProgress(temporaryDirectory, snapshots::add, 2, 3, false,
				sampler)) {
			verify(sampler).scheduleAtFixedRate(scheduledSample.capture(), eq(1L), eq(1L), eq(TimeUnit.SECONDS));
			progress.startPhase(BulkLoadPhase.STAGE_INPUTS);

			progress.operations(999_999L, 0L);
			Files.delete(temporaryDirectory.resolve("progress.properties"));
			scheduledSample.getValue().run();

			assertThat(temporaryDirectory.resolve("progress.properties")).isRegularFile();
			assertThat(snapshots)
					.extracting(ProgressSnapshot::phaseOperations)
					.containsExactly(0L);

			progress.operations(1L, 0L);

			assertThat(snapshots)
					.extracting(ProgressSnapshot::phaseOperations)
					.containsExactly(0L, 1_000_000L);
		}
	}

	@Test
	void phaseCompletionReportsRemainingOperationsWithNonzeroThroughput() {
		List<ProgressSnapshot> snapshots = new ArrayList<>();
		try (BulkLoadProgress progress = new BulkLoadProgress(temporaryDirectory, snapshots::add, 2, 3, false)) {
			progress.startPhase(BulkLoadPhase.DISTINCT_AND_ANALYZE_VALUES);
			progress.operations(500_000L, 0L);
			progress.completePhase(BulkLoadPhase.DISTINCT_AND_ANALYZE_VALUES);

			assertThat(snapshots.getLast().phaseComplete()).isTrue();
			assertThat(snapshots.getLast().phaseOperations()).isEqualTo(500_000L);
			assertThat(snapshots.getLast().currentOperationsPerSecond()).isPositive();
		}
	}

	@Test
	void phaseCompletionPreservesTheRateAfterThresholdUpdate() {
		List<ProgressSnapshot> snapshots = new ArrayList<>();
		try (BulkLoadProgress progress = new BulkLoadProgress(temporaryDirectory, snapshots::add, 2, 3, false)) {
			progress.startPhase(BulkLoadPhase.STAGE_INPUTS);
			progress.operations(1_000_000L, 0L);
			int listenerUpdatesBeforeCompletion = snapshots.size();

			progress.completePhase(BulkLoadPhase.STAGE_INPUTS);

			assertThat(snapshots).hasSize(listenerUpdatesBeforeCompletion + 1);
			assertThat(snapshots.getLast().phaseComplete()).isTrue();
			assertThat(snapshots.getLast().currentOperationsPerSecond()).isPositive();
		}
	}

}
